sys_ux_client_script.script:
/**
 * Evaluates and returns an element or element_level2 value based on conditions.
 *
 * @param {Object} params - The function parameters.
 * @param {Object} params.api - API object containing data and state.
 * @param {number} params.i - The starting index for iteration.
 * @returns {string|null} - The corresponding element or element_level2 value, or null if waiting.
 */
function evaluateProperty({ api, i = 1 }) {
    const clientStateParameter = api.state.Tab11stBreakdown;

    // Get the length of the daily frequency dataset
    const dailyLength = api.state.elementsDeploymentFrequencyDaily.length;

    // Check if i is within the daily frequency length
    if (i >= dailyLength) {
        return null; // Waiting for further instructions
    }

    // Extract daily value at index i
    const dailyResult = api.data.verticalC_headlinemetric2_daily?.output?.result[i];

    // Return the appropriate element based on client state
    return clientStateParameter === ''
        ? dailyResult?.element.display_value
        : dailyResult?.element_level2.display_value;
}
